import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.C8wZ88_B.js";const p=JSON.parse(`{"title":"Activité — Le trajet d'une page Web","description":"","frontmatter":{"title":"Activité — Le trajet d'une page Web","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/activite-casse-tete.md","filePath":"modules/01-faisabilite/activite-casse-tete.md"}`),s={name:"modules/01-faisabilite/activite-casse-tete.md"};function i(l,e,o,d,u,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="activite-—-le-trajet-d-une-page-web" tabindex="-1">Activité — Le trajet d&#39;une page Web <a class="header-anchor" href="#activite-—-le-trajet-d-une-page-web" aria-label="Permalink to &quot;Activité — Le trajet d&#39;une page Web&quot;">​</a></h1><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Objectif de l&#39;activité</strong><br> Reconstruire, avec vos propres mots, tout ce qui doit exister pour qu&#39;une personne voie le site d&#39;un restaurant sur son téléphone. </div><h2 id="mise-en-situation" tabindex="-1">Mise en situation <a class="header-anchor" href="#mise-en-situation" aria-label="Permalink to &quot;Mise en situation&quot;">​</a></h2><p>Une cliente tape <code>bistro-exemple.ca</code> dans son téléphone pour consulter le menu et réserver une table. En quelques secondes, la page s&#39;affiche. <strong>Que s&#39;est-il passé entre les deux ?</strong></p><hr><h2 id="les-cartes" tabindex="-1">Les cartes <a class="header-anchor" href="#les-cartes" aria-label="Permalink to &quot;Les cartes&quot;">​</a></h2><p>Les cartes sont volontairement <strong>mélangées</strong>. Elles sont aussi disponibles sur le tableau blanc partagé de la séance.</p><table tabindex="0"><thead><tr><th style="text-align:center;"></th><th style="text-align:left;">Carte</th></tr></thead><tbody><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Contenus</strong> (textes, photos, menu, heures d&#39;ouverture)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Navigateur</strong> (Chrome, Safari, Firefox…)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Certificat SSL/TLS</strong> (le cadenas)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Nom de domaine</strong> (<code>bistro-exemple.ca</code>)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Service externe</strong> (réservation, paiement, livraison)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Hébergement</strong> (le serveur où vit le site)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Appareil</strong> (téléphone, tablette, ordinateur)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>DNS</strong> (l&#39;annuaire qui traduit le nom en adresse)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Plateforme</strong> (WordPress, Shopify, Wix, code maison…)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Registraire</strong> (l&#39;entreprise où on loue le nom de domaine)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>CDN</strong> (réseau de serveurs qui rapproche le site des visiteurs)</td></tr><tr><td style="text-align:center;">🟦</td><td style="text-align:left;"><strong>Courriel professionnel</strong> (<code>info@bistro-exemple.ca</code>)</td></tr></tbody></table><hr><h2 id="consignes" tabindex="-1">Consignes <a class="header-anchor" href="#consignes" aria-label="Permalink to &quot;Consignes&quot;">​</a></h2><h3 id="etape-1-—-le-trajet-10-min" tabindex="-1">Étape 1 — Le trajet (10 min) <a class="header-anchor" href="#etape-1-—-le-trajet-10-min" aria-label="Permalink to &quot;Étape 1 — Le trajet (10 min)&quot;">​</a></h3><p>Placez les cartes <strong>dans l&#39;ordre du trajet</strong>, de la cliente qui tape l&#39;adresse jusqu&#39;à la page affichée. Reliez-les par des flèches.</p><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Attention</strong><br> Certaines cartes ne se placent pas directement sur le trajet. Mettez-les à côté et expliquez à quoi elles servent. </div><h3 id="etape-2-—-qui-paie-quoi-5-min" tabindex="-1">Étape 2 — Qui paie quoi ? (5 min) <a class="header-anchor" href="#etape-2-—-qui-paie-quoi-5-min" aria-label="Permalink to &quot;Étape 2 — Qui paie quoi ? (5 min)&quot;">​</a></h3><p>Pour chaque carte, indiquez :</p><ul><li><strong>qui la fournit</strong> (une entreprise, le restaurant lui-même, la cliente…) ;</li><li>si elle est <strong>gratuite ou payante</strong> ;</li><li>si on la paie <strong>une seule fois</strong> ou <strong>chaque mois / chaque année</strong>.</li></ul><h3 id="etape-3-—-mise-en-commun" tabindex="-1">Étape 3 — Mise en commun <a class="header-anchor" href="#etape-3-—-mise-en-commun" aria-label="Permalink to &quot;Étape 3 — Mise en commun&quot;">​</a></h3><p>On compare les trajets. Là où les équipes ne sont pas d&#39;accord, c&#39;est souvent là que se cache une notion importante.</p><p>Suite : <a href="./01-mettre-un-site-en-ligne#le-trajet-d-une-page-web">Séance 1 — Ce qu&#39;il faut pour mettre un site en ligne</a></p>',19)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
